    'interquartile-range-calculator' => 
    array (
      'title' => 'Interquartile Range Calculator - IQR Dispersion Tool',
      'h1' => 'Interquartile Range (IQR] Calculator',
      'subtitle' => 'Calculate the middle 50% spread of your data.',
      'description' => 'Find the IQR (difference between Q3 and Q1] to measure variability while ignoring extreme outliers.',
      'icon' => 'fas fa-arrows-to-circle',
