    'median-absolute-deviation-calculator' => 
    array (
      'title' => 'Median Absolute Deviation Calculator - Robust Spread Tool',
      'h1' => 'Median Absolute Deviation (MAD] Calculator',
      'subtitle' => 'Calculate the most robust measure of data dispersion.',
      'description' => 'Find the MAD (Median of absolute deviations from the median] to analyze volatility in data with heavy outliers.',
      'icon' => 'fas fa-shield-halved',
      'category' => 'calculators',
      'type' => 'interactive',
      'processor' => 'interactive',
      'pro_config' => 
