    'anova-calculator' => 
    array (
      'title' => 'ANOVA Calculator - Analysis of Variance Tool',
      'h1' => 'One-Way ANOVA Calculator',
      'subtitle' => 'Compare means across three or more groups.',
      'description' => 'Perform a one-way Analysis of Variance (ANOVA] to determine if there are statistically significant differences between group means.',
      'icon' => 'fas fa-layer-group',
      'category' => 'calculators',
      'type' => 'interactive',
      'processor' => 'interactive',
      'pro_config' => 
      array (
        'mode' => 'pro',
        'inputs' => 
        array (
          'basic' => 
