    'chi-square-calculator' => 
    array (
      'title' => 'Chi-Square Calculator - Goodness of Fit Tool',
      'h1' => 'Chi-Square Test Calculator',
      'subtitle' => 'Test if observed data matches expected patterns.',
      'description' => 'Calculate the Chi-Square (ÃƒÂÃ¢â‚¬Â¡Ãƒâ€šÃ‚Â²] statistic to compare observed frequencies with expected frequencies in categorical data.',
      'icon' => 'fas fa-chart-line',
      'category' => 'calculators',
      'type' => 'interactive',
      'processor' => 'interactive',
      'pro_config' => 
      array (
        'mode' => 'pro',
        'inputs' => 
        array (
          'basic' => 
          array (
            0 => 
            array (
              'id' => 'observed',
              'label' => 'Observed Frequencies',
              'type' => 'interactive',
              'default' => '20, 30, 50',
