    'linear-regression-calculator' => 
    array (
      'title' => 'Linear Regression Calculator - Least Squares Tool',
      'h1' => 'Linear Regression Calculator',
      'subtitle' => 'Find the line of best fit.',
      'description' => 'Calculate the intercept, slope, and regression equation (y = mx + b] for a set of paired data.',
      'icon' => 'fas fa-arrow-trend-up',
      'category' => 'calculators',
      'type' => 'interactive',
      'processor' => 'interactive',
      'pro_config' => 
      array (
        'mode' => 'pro',
        'inputs' => 
        array (
          'basic' => 
          array (
            0 => 
            array (
              'id' => 'x_vals',
              'label' => 'Independent Variable (X]',
