    'continued-fraction-calculator' => 
    array (
      'title' => 'Continued Fraction Calculator - Expansion & Convergents Tool',
      'h1' => 'Continued Fraction Calculator',
      'subtitle' => 'Expand any real number or fraction into a continued fraction.',
      'description' => 'A powerful number theory utility to find the continued fraction representation and the series of convergents for any numerical input.',
