      'subtitle' => 'Calculate the convolution of two discrete sequences.',
      'description' => 'A professional utility for digital signal processing (DSP] and system analysis.',
      'icon' => 'fas fa-wave-square',
      'category' => 'calculators',
      'type' => 'interactive',
      'processor' => 'interactive',
      'pro_config' => 
      array (
        'mode' => 'pro',
        'inputs' => 
        array (
