    'html-beautifier' => 
    array (
      'title' => 'HTML Beautifier - Free Online Code Formatter',
      'h1' => 'HTML Beautifier',
      'subtitle' => 'Turn messy, minified HTML into clean, readable code instantly.',
      'description' => 'A professional HTML formatter that applies consistent indentation and formatting to your web markup.',
      'icon' => 'fab fa-html5',
      'category' => 'text',
