    'redirect-checker' => 
    array (
      'title' => 'Redirect Checker - URL Chain & Status Tool',
      'h1' => 'Professional Redirect Checker',
      'subtitle' => 'Audit the path of any URL to identify redirect chains and loops.',
      'description' => 'A high-fidelity SEO utility to follow URL hops, status codes, and final destinations with sub-second accuracy.',
      'icon' => 'fas fa-route',
      'category' => 'webmaster',
      'type' => 'interactive',
      'processor' => 'interactive',
      'pro_config' => 
      array (
        'mode' => 'pro',
        'inputs' => 
        array (
          'basic' => 
          array (
            0 => 
            array (
              'id' => 'url',
              'label' => 'Standard URL',
